import 'package:flutter/material.dart';import 'package:url_launcher/url_launcher.dart';import 'work_order_start_dialog.dart';import 'work_order_status_chip.dart';
class WorkOrderPhoto{final String label,source;const WorkOrderPhoto(this.label,this.source);}
class BrandedWorkOrderCard extends StatelessWidget{final String code,typeLabel,status,finding,feeder,section,date,coordinate;final List<WorkOrderPhoto> photos;final bool waiting,finished;final VoidCallback onStart,onOpen;const BrandedWorkOrderCard({super.key,required this.code,required this.typeLabel,required this.status,required this.finding,required this.feeder,required this.section,required this.date,required this.coordinate,required this.photos,required this.waiting,required this.finished,required this.onStart,required this.onOpen});Future<void> _start(BuildContext c)async{if(await showWorkOrderStartDialog(c,code:code,module:typeLabel,title:finding.isEmpty?feeder:finding,detail:[feeder,section].where((v)=>v.isNotEmpty).join(' • ')))onStart();}@override Widget build(BuildContext c)=>Container(margin:const EdgeInsets.only(bottom:18),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFFFBFDFE),borderRadius:BorderRadius.circular(22),border:Border.all(color:const Color(0xFFDCE8EC)),boxShadow:const[BoxShadow(color:Color(0x18063B5C),blurRadius:24,offset:Offset(0,10))]),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(code,style:const TextStyle(color:Color(0xFF004D8C),fontWeight:FontWeight.w900)),const SizedBox(height:10),WorkOrderStatusChip(status:status,waiting:waiting,finished:finished),const SizedBox(height:8),Text(finding.isEmpty?'Temuan belum tersedia':finding,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w900)),Text(feeder,style:const TextStyle(fontWeight:FontWeight.w800)),Text(section,style:const TextStyle(color:Color(0xFF667D86),fontSize:11)),const SizedBox(height:10),Row(children:[Expanded(child:Text('Tanggal WO  $date',style:const TextStyle(color:Color(0xFF667D86),fontSize:11))),waiting?ElevatedButton(onPressed:()=>_start(c),child:const Text('Mulai')):OutlinedButton(onPressed:onOpen,child:Text(finished?'Lihat':'Lanjutkan'))]) ]));}
